package org.cao.backend.operational;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class CanonicalAuditTest {

    /**
     * Rows generated by the Go audit.go (CanonicalAuditRecord/AuditChainHash) at the baseline SHA.
     * Java must reproduce the exact record bytes and chain hashes so each can verify the other's rows.
     */
    @Test
    void reproducesGoCanonicalRecordsAndChainHashes() throws IOException {
        String[] lines = resource("go-audit-vectors.tsv").split("\n");
        assertEquals(4, lines.length);
        Instant t = Instant.parse("2026-10-02T14:25:38.120Z");
        List<AuditEvent> events = List.of(
            new AuditEvent(1, t, "admin.rebuild.admitted", "success", "octocat",
                Map.of("rebuild_id", "r-1", "a", "b")),
            new AuditEvent(2, t.plusMillis(880), "token.revoked", "denied", "", Map.of()),
            new AuditEvent(3, t.plusSeconds(1), "x<y>&z", "failure", "ünï\u2028\u2029",
                Map.of("k\"q", "line\nfeed\ttab\\ \b\f\r \u0001 \u007f é \uD83D\uDE00")),
            new AuditEvent(4, t.plusSeconds(2), "e", "success", "",
                Map.of("\uD83D\uDE00", "a", "\uFF5E", "b", "Z", "c", "a", "d")));
        byte[] previous = CanonicalAudit.genesis();
        for (int i = 0; i < lines.length; i++) {
            String[] columns = lines[i].split("\t");
            byte[] record = CanonicalAudit.record(events.get(i));
            assertEquals(columns[1], new String(record, StandardCharsets.UTF_8), "record " + (i + 1));
            previous = CanonicalAudit.chainHash(previous, record);
            assertEquals(columns[2], CanonicalAudit.hex(previous), "hash " + (i + 1));
        }
    }

    @Test
    void timeUsesShortestFractionLikeGo() {
        assertEquals("2026-01-02T03:04:05Z", CanonicalAudit.time(Instant.parse("2026-01-02T03:04:05Z")));
        assertEquals("2026-01-02T03:04:05.007Z",
            CanonicalAudit.time(Instant.parse("2026-01-02T03:04:05.007Z")));
        assertEquals("2026-01-02T03:04:05.12Z",
            CanonicalAudit.time(Instant.parse("2026-01-02T03:04:05.120Z")));
    }

    @Test
    void chainHashStartsFromAllZeroGenesis() {
        assertEquals(64, CanonicalAudit.genesisHex().length());
        assertArrayEquals(new byte[32], CanonicalAudit.genesis());
    }

    @Test
    void oversizedRecordIsRejected() {
        Map<String, String> attributes = new java.util.HashMap<>();
        for (int i = 0; i < 40; i++) {
            attributes.put("k" + i, "x".repeat(2000));
        }
        AuditEvent event = new AuditEvent(1, Instant.EPOCH, "e", "success", "", attributes);
        assertThrows(AuditInputException.class, () -> CanonicalAudit.record(event));
    }

    private static String resource(String name) throws IOException {
        try (InputStream in = CanonicalAuditTest.class.getResourceAsStream(name)) {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8).stripTrailing();
        }
    }
}
